import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type ChameleonAnimationProps = Record<string, any>;

const ChameleonAnimation: React.FC<ChameleonAnimationProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 8,
  chameleonColor = "#10b981",
  accentColor = "#047857",
  branchColor = "#78350f",
  bugColor = "#eab308",
  bugDistance = 200,
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Background transparency logic
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Entry Animations
  const branchEntry = spring({
    frame: frame,
    fps,
    config: { damping: 12, stiffness: 100 },
  });
  
  const chameleonEntry = spring({
    frame: frame - 15,
    fps,
    config: { damping: 14, stiffness: 120 },
  });
  
  const bugEntry = spring({
    frame: frame - 30,
    fps,
    config: { damping: 10, stiffness: 150 },
  });

  // Idle Animations
  const breathScale = 1 + Math.sin(frame / 15) * 0.02;
  const cycle = frame % 150;
  const eyeScaleY = interpolate(
    cycle,
    [0, 140, 143, 146, 150],
    [1, 1, 0.1, 1, 1],
    { extrapolateRight: "clamp" }
  );

  // Tongue Strike Logic
  const strikeFrame = Math.floor((durationInSeconds * fps) / 2);
  const tongueOut = spring({
    frame: frame - strikeFrame,
    fps,
    config: { damping: 10, stiffness: 400 },
  });
  const tongueIn = spring({
    frame: frame - (strikeFrame + 8),
    fps,
    config: { damping: 12, stiffness: 300 },
  });
  const tongueFactor = Math.max(0, tongueOut - tongueIn);

  // Bug Positioning
  const baseBugX = 750 + bugDistance;
  const baseBugY = 250;
  const bugHoverX = baseBugX + Math.sin(frame / 15) * 30;
  const bugHoverY = baseBugY + Math.cos(frame / 12) * 40;

  const tongueTipX = interpolate(tongueFactor, [0, 1], [740, bugHoverX], {
    extrapolateRight: "extend",
    extrapolateLeft: "clamp",
  });
  const tongueTipY = interpolate(tongueFactor, [0, 1], [355, bugHoverY], {
    extrapolateRight: "extend",
    extrapolateLeft: "clamp",
  });

  const hitFrame = strikeFrame + 6;
  const isEaten = frame >= hitFrame;
  const renderBugX = isEaten ? tongueTipX : bugHoverX;
  const renderBugY = isEaten ? tongueTipY : bugHoverY;

  const bugEatenScale = interpolate(tongueIn, [0.8, 1], [1, 0], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const finalBugScale = bugEntry * bugEatenScale;

  // Eye Tracking Logic
  const eyeAngle = Math.atan2(renderBugY - 290, renderBugX - 680);
  const eyeDistance = 12;
  const eyeX = 680 + Math.cos(eyeAngle) * eyeDistance;
  const eyeY = 290 + Math.sin(eyeAngle) * eyeDistance;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div style={{ width: "85%", height: "85%", position: "relative" }}>
        <svg
          viewBox="0 0 1000 600"
          style={{ width: "100%", height: "100%", overflow: "visible", transition: "none" }}
        >
          {/* Ambient Background Elements */}
          <g opacity="0.3" transform={`scale(${branchEntry})`} transform-origin="500 300">
            <circle cx="100" cy="100" r="250" fill={accentColor} opacity="0.1" />
            <circle cx="900" cy="500" r="350" fill={accentColor} opacity="0.1" />
          </g>

          {/* Branch Layer */}
          <g opacity={branchEntry}>
            <path
              d="M -100 500 Q 500 480 1100 450"
              stroke={branchColor}
              strokeWidth="25"
              fill="none"
              strokeLinecap="round"
            />
            {/* Small Twigs */}
            <path
              d="M 300 490 Q 350 440 400 450"
              stroke={branchColor}
              strokeWidth="12"
              fill="none"
              strokeLinecap="round"
            />
            <path
              d="M 800 465 Q 850 415 900 435"
              stroke={branchColor}
              strokeWidth="12"
              fill="none"
              strokeLinecap="round"
            />
            {/* Leaves */}
            <path d="M 400 450 Q 420 410 390 390 Q 370 420 400 450" fill={accentColor} />
            <path d="M 900 435 Q 940 445 950 475 Q 910 475 900 435" fill={accentColor} />
          </g>

          {/* Bug Layer */}
          <g transform={`translate(${renderBugX}, ${renderBugY}) scale(${finalBugScale})`}>
            {/* Rapidly flapping wings */}
            <ellipse
              cx="-6"
              cy="-8"
              rx="8"
              ry="14"
              fill="#f8fafc"
              opacity="0.8"
              transform={`rotate(${Math.sin(frame) * 45})`}
            />
            <ellipse
              cx="6"
              cy="-8"
              rx="8"
              ry="14"
              fill="#f8fafc"
              opacity="0.8"
              transform={`rotate(${-Math.sin(frame) * 45})`}
            />
            <circle cx="0" cy="0" r="10" fill={bugColor} />
          </g>

          {/* Chameleon Layer */}
          <g transform={`scale(${chameleonEntry})`} transform-origin="500 400">
            <g transform={`scale(1, ${breathScale})`} transform-origin="500 400">
              
              {/* Back Legs (Darker/Behind) */}
              <g stroke={accentColor} strokeWidth="20" strokeLinecap="round" strokeLinejoin="round" fill="none">
                <path d="M 400 400 L 380 460 L 400 500" />
                <path d="M 400 500 C 380 510, 380 520, 390 520" strokeWidth="15" />
                <path d="M 400 500 C 420 510, 420 520, 410 520" strokeWidth="15" />
                <path d="M 600 380 L 620 440 L 600 480" />
                <path d="M 600 480 C 580 490, 580 500, 590 500" strokeWidth="15" />
                <path d="M 600 480 C 620 490, 620 500, 610 500" strokeWidth="15" />
              </g>

              {/* Curled Tail */}
              <path
                d="M 320 380 C 150 380, 150 600, 250 600 C 330 600, 330 480, 270 480 C 220 480, 220 560, 260 560 C 280 560, 280 520, 270 520"
                stroke={chameleonColor}
                strokeWidth="35"
                fill="none"
                strokeLinecap="round"
              />

              {/* Main Body */}
              <path
                d="M 310 390 C 350 200, 600 220, 650 350 C 650 450, 450 480, 310 390 Z"
                fill={chameleonColor}
              />

              {/* Body Accents / Spots */}
              <circle cx="450" cy="300" r="18" fill={accentColor} opacity="0.6" />
              <circle cx="520" cy="280" r="14" fill={accentColor} opacity="0.6" />
              <circle cx="580" cy="300" r="10" fill={accentColor} opacity="0.6" />
              <circle cx="400" cy="340" r="12" fill={accentColor} opacity="0.6" />

              {/* Front Legs */}
              <g stroke={chameleonColor} strokeWidth="20" strokeLinecap="round" strokeLinejoin="round" fill="none">
                <path d="M 430 400 L 450 450 L 430 490" />
                <path d="M 430 490 C 410 500, 410 510, 420 510" strokeWidth="15" />
                <path d="M 430 490 C 450 500, 450 510, 440 510" strokeWidth="15" />
                <path d="M 640 380 L 660 430 L 640 470" />
                <path d="M 640 470 C 620 480, 620 490, 630 490" strokeWidth="15" />
                <path d="M 640 470 C 660 480, 660 490, 650 490" strokeWidth="15" />
              </g>

              {/* Casque (Helmet) */}
              <path d="M 580 300 C 580 150, 720 180, 680 320 Z" fill={chameleonColor} />

              {/* Face and Snout */}
              <path
                d="M 600 250 C 750 250, 800 320, 750 380 C 700 420, 580 420, 580 250 Z"
                fill={chameleonColor}
              />

              {/* Mouth Line */}
              <path
                d="M 750 360 C 700 360, 650 370, 610 390"
                stroke={accentColor}
                strokeWidth="4"
                fill="none"
                strokeLinecap="round"
              />

              {/* Tongue Base / Sticky End */}
              {tongueFactor > 0 && (
                <>
                  <line
                    x1="740"
                    y1="355"
                    x2={tongueTipX}
                    y2={tongueTipY}
                    stroke="#ef4444"
                    strokeWidth="12"
                    strokeLinecap="round"
                  />
                  <circle cx={tongueTipX} cy={tongueTipY} r="14" fill="#ef4444" />
                </>
              )}

              {/* Eye Cone Background */}
              <g transform={`scale(1, ${eyeScaleY})`} transform-origin="680 290">
                <circle
                  cx="680"
                  cy="290"
                  r="30"
                  fill={chameleonColor}
                  stroke={accentColor}
                  strokeWidth="4"
                />
                {/* Eye Pupil */}
                <circle cx={eyeX} cy={eyeY} r="12" fill="#0f172a" />
                <circle cx={eyeX - 4} cy={eyeY - 4} r="4" fill="#ffffff" opacity="0.8" />
              </g>

            </g>
          </g>
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default ChameleonAnimation;